class Solution {
public:
    int countOdds(int low, int high) {
        long long oddUpToHigh = (static_cast<long long>(high) + 1) / 2;
        long long oddUpToLowMinusOne = static_cast<long long>(low) / 2;
        return static_cast<int>(oddUpToHigh - oddUpToLowMinusOne);
    }
};

code.java:
class Solution {
    public int countOdds(int low, int high) {
        long oddUpToHigh = (long) (high + 1) / 2;
        long oddUpToLowMinusOne = (long) low / 2;
        return (int) (oddUpToHigh - oddUpToLowMinusOne);
    }
}

code.javascript:
/**
 * @param {number} low
 * @param {number} high
 * @return {number}
 */
var countOdds = function(low, high) {
    const oddUpToHigh = Math.floor((high + 1) / 2);
    const oddUpToLowMinusOne = Math.floor(low / 2);
    return oddUpToHigh - oddUpToLowMinusOne;
};
